package com.circlenet.domain.message.model;
import jakarta.persistence.*;import java.time.Instant;
@Entity @Table(name="direct_message_reactions") public class DirectMessageReactionEntity {@Id @GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@Column(name="message_id",nullable=false)private Long messageId;@Column(name="user_id",nullable=false)private Long userId;@Column(nullable=false,length=16)private String emoji;@Column(name="created_at",nullable=false)private Instant createdAt=Instant.now();public Long getId(){return id;}public Long getMessageId(){return messageId;}public void setMessageId(Long v){messageId=v;}public Long getUserId(){return userId;}public void setUserId(Long v){userId=v;}public String getEmoji(){return emoji;}public void setEmoji(String v){emoji=v;}public Instant getCreatedAt(){return createdAt;}}
